package com.mahesh.empleave.holiday;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController @RequestMapping("/api/holidays") @RequiredArgsConstructor public class HolidayController{private final HolidayRepository repo;private final UserRepository users;private final AuditService audit;record Input(@NotNull LocalDate date,@NotBlank @Size(max=160) String name){}@GetMapping Page<ApiDtos.Holiday> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return repo.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("holidayDate"))).map(ApiDtos::holiday);}@PostMapping @PreAuthorize("hasRole('ADMIN')") ApiDtos.Holiday add(Authentication a,@RequestBody @jakarta.validation.Valid Input x){var h=repo.save(new Holiday(x.date(),x.name()));audit.log(users.findByEmail(a.getName()).orElseThrow(),"HOLIDAY_CREATED","HOLIDAY",h.getId());return ApiDtos.holiday(h);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ApiDtos.Holiday update(Authentication a,@PathVariable Long id,@RequestBody @jakarta.validation.Valid Input x){var h=repo.findById(id).orElseThrow();h.update(x.date(),x.name());audit.log(users.findByEmail(a.getName()).orElseThrow(),"HOLIDAY_UPDATED","HOLIDAY",id);return ApiDtos.holiday(h);}}
